using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using IDSFintech.Api.Repositories; using Microsoft.IdentityModel.Tokens;
namespace IDSFintech.Api.Services;
public sealed class JwtService(IConfiguration config) { public string Create(UserLogin u) { var j=config.GetSection("Jwt"); var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(j["Key"]!)); var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.Username),new Claim(ClaimTypes.Role,u.RoleName)}; return new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken(j["Issuer"],j["Audience"],claims,expires:DateTime.UtcNow.AddMinutes(j.GetValue<int>("ExpiryMinutes")),signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256))); } }
